local P=workspace:FindFirstChild("Patch_v40") assert(P,"Patch_v40 absent de Workspace") local function cible(path) local o=game for seg in string.gmatch(path,"[^/]+") do o=o:FindFirstChild(seg) if not o then return nil end end return o end local n,manque=0,{} for _,s in ipairs(P.Sources:GetChildren()) do local t=cible(s.Name) if t then local neuf=s:Clone() neuf.Name=t.Name if neuf:IsA("Script") then neuf.Disabled=t.Disabled end for _,c in ipairs(t:GetChildren()) do c.Parent=neuf end neuf.Parent=t.Parent t:Destroy() n+=1 else table.insert(manque,s.Name) end end for _,d in ipairs(P.Inserts:GetChildren()) do local t=cible(d.Name) if t then for _,c in ipairs(d:GetChildren()) do local old=t:FindFirstChild(c.Name) if old then old:Destroy() end c.Parent=t n+=1 end else table.insert(manque,d.Name) end end for _,c in ipairs(game.StarterGui:GetChildren()) do c:Destroy() end for _,c in ipairs(P.StarterGui:GetChildren()) do c.Parent=game.StarterGui n+=1 end P:Destroy() print("PATCH v40 OK :",n,"remplacements ; manquants :",table.concat(manque,", "))
